-- v4.4.3 governed Security Domain administration and legacy collaboration-group binding.
DECLARE
  PROCEDURE ddl(s VARCHAR2) IS BEGIN EXECUTE IMMEDIATE s; EXCEPTION WHEN OTHERS THEN IF SQLCODE != -955 THEN RAISE; END IF; END;
BEGIN
  ddl('CREATE TABLE CX_DOMAIN_GOVERNANCE (SECURITY_DOMAIN_ID VARCHAR2(128) PRIMARY KEY,OWNER_PRINCIPAL_ID VARCHAR2(128) NOT NULL,REASON VARCHAR2(2000) NOT NULL,UPDATED_BY VARCHAR2(128) NOT NULL,UPDATED_AT TIMESTAMP DEFAULT CURRENT_TIMESTAMP NOT NULL)');
  ddl('CREATE TABLE CX_DOMAIN_BINDINGS (BINDING_ID VARCHAR2(128) PRIMARY KEY,SECURITY_DOMAIN_ID VARCHAR2(128) NOT NULL,BINDING_TYPE VARCHAR2(32) NOT NULL CHECK (BINDING_TYPE IN (''CHANNEL'',''LEGACY_COLLAB_GROUP'')),TARGET_ID VARCHAR2(128) NOT NULL,STATUS VARCHAR2(32) DEFAULT ''DRAFT'' NOT NULL CHECK (STATUS IN (''DRAFT'',''ACTIVE'',''SUSPENDED'',''REVOKED'',''SUPERSEDED'')),REASON VARCHAR2(2000) NOT NULL,APPROVAL_REF VARCHAR2(256),CREATED_BY VARCHAR2(128) NOT NULL,CREATED_AT TIMESTAMP DEFAULT CURRENT_TIMESTAMP NOT NULL,UPDATED_AT TIMESTAMP DEFAULT CURRENT_TIMESTAMP NOT NULL)');
  ddl('CREATE INDEX IDX_CX_DOMAIN_BINDINGS_DOMAIN ON CX_DOMAIN_BINDINGS(SECURITY_DOMAIN_ID,STATUS,CREATED_AT)');
  ddl('CREATE UNIQUE INDEX UK_CX_DOMAIN_ACTIVE_GROUP ON CX_DOMAIN_BINDINGS(CASE WHEN BINDING_TYPE=''LEGACY_COLLAB_GROUP'' AND STATUS=''ACTIVE'' THEN TARGET_ID END)');
  ddl('CREATE UNIQUE INDEX UK_CX_DOMAIN_ACTIVE_TARGET ON CX_DOMAIN_BINDINGS(CASE WHEN STATUS=''ACTIVE'' THEN SECURITY_DOMAIN_ID END,CASE WHEN STATUS=''ACTIVE'' THEN BINDING_TYPE END,CASE WHEN STATUS=''ACTIVE'' THEN TARGET_ID END)');
  ddl('CREATE TABLE CX_DOMAIN_CONVERSION_DRAFTS (DRAFT_ID VARCHAR2(128) PRIMARY KEY,SOURCE_GROUP_ID VARCHAR2(128) NOT NULL,PROPOSED_DOMAIN_ID VARCHAR2(128) NOT NULL,DOMAIN_NAME VARCHAR2(256) NOT NULL,CLASSIFICATION VARCHAR2(32) NOT NULL,PURPOSE VARCHAR2(1000) NOT NULL,OWNER_PRINCIPAL_ID VARCHAR2(128) NOT NULL,SNAPSHOT_JSON CLOB NOT NULL,STATUS VARCHAR2(32) DEFAULT ''DRAFT'' NOT NULL CHECK (STATUS IN (''DRAFT'',''REVIEW'',''APPROVED'',''APPLIED'',''REJECTED'',''EXPIRED'',''FAILED'')),REASON VARCHAR2(2000) NOT NULL,APPROVAL_REF VARCHAR2(256),CREATED_BY VARCHAR2(128) NOT NULL,APPLIED_BY VARCHAR2(128),APPLIED_AT TIMESTAMP,CREATED_AT TIMESTAMP DEFAULT CURRENT_TIMESTAMP NOT NULL,UPDATED_AT TIMESTAMP DEFAULT CURRENT_TIMESTAMP NOT NULL)');
  ddl('CREATE INDEX IDX_CX_DOMAIN_CONVERSION_GROUP ON CX_DOMAIN_CONVERSION_DRAFTS(SOURCE_GROUP_ID,STATUS,CREATED_AT)');
  ddl('CREATE TABLE CX_DOMAIN_DRAFT_MEMBERS (DRAFT_MEMBER_ID VARCHAR2(128) PRIMARY KEY,DRAFT_ID VARCHAR2(128) NOT NULL,PRINCIPAL_ID VARCHAR2(128) NOT NULL,PRINCIPAL_TYPE VARCHAR2(16) NOT NULL CHECK (PRINCIPAL_TYPE IN (''HUMAN'',''AGENT'')),MEMBERSHIP_TIER VARCHAR2(32) DEFAULT ''MEMBER'' NOT NULL,VALID_UNTIL TIMESTAMP,DECISION VARCHAR2(32) DEFAULT ''PENDING'' NOT NULL CHECK (DECISION IN (''PENDING'',''CONFIRMED'',''REJECTED'')),REVIEWED_BY VARCHAR2(128),REVIEWED_AT TIMESTAMP,REVIEW_REASON VARCHAR2(2000),CONSTRAINT UK_CX_DOMAIN_DRAFT_MEMBER UNIQUE(DRAFT_ID,PRINCIPAL_ID))');
  ddl('CREATE INDEX IDX_CX_DOMAIN_DRAFT_MEMBERS ON CX_DOMAIN_DRAFT_MEMBERS(DRAFT_ID,DECISION,PRINCIPAL_TYPE)');
END;
/
MERGE INTO CX_PLATFORM_CAPABILITIES d USING (SELECT 'security_domains' CAPABILITY_KEY FROM DUAL) s ON (d.CAPABILITY_KEY=s.CAPABILITY_KEY)
WHEN NOT MATCHED THEN INSERT(CAPABILITY_KEY,ENABLED,MANDATORY,VERSION,UPDATED_BY,UPDATE_REASON) VALUES('security_domains','Y','Y',1,'SYSTEM','Security Domain governance is a mandatory zero-trust boundary');
MERGE INTO CX_PLATFORM_CAPABILITY_DEPENDENCIES d USING (SELECT 'security_domains' CAPABILITY_KEY,'identity' DEPENDS_ON_KEY FROM DUAL) s ON (d.CAPABILITY_KEY=s.CAPABILITY_KEY AND d.DEPENDS_ON_KEY=s.DEPENDS_ON_KEY) WHEN NOT MATCHED THEN INSERT(CAPABILITY_KEY,DEPENDS_ON_KEY) VALUES(s.CAPABILITY_KEY,s.DEPENDS_ON_KEY);
MERGE INTO CX_PLATFORM_CAPABILITY_DEPENDENCIES d USING (SELECT 'security_domains' CAPABILITY_KEY,'authorization' DEPENDS_ON_KEY FROM DUAL) s ON (d.CAPABILITY_KEY=s.CAPABILITY_KEY AND d.DEPENDS_ON_KEY=s.DEPENDS_ON_KEY) WHEN NOT MATCHED THEN INSERT(CAPABILITY_KEY,DEPENDS_ON_KEY) VALUES(s.CAPABILITY_KEY,s.DEPENDS_ON_KEY);
MERGE INTO CX_PLATFORM_CAPABILITY_DEPENDENCIES d USING (SELECT 'security_domains' CAPABILITY_KEY,'audit_write' DEPENDS_ON_KEY FROM DUAL) s ON (d.CAPABILITY_KEY=s.CAPABILITY_KEY AND d.DEPENDS_ON_KEY=s.DEPENDS_ON_KEY) WHEN NOT MATCHED THEN INSERT(CAPABILITY_KEY,DEPENDS_ON_KEY) VALUES(s.CAPABILITY_KEY,s.DEPENDS_ON_KEY);
MERGE INTO CX_PLATFORM_CAPABILITY_DEPENDENCIES d USING (SELECT 'security_domains' CAPABILITY_KEY,'channels' DEPENDS_ON_KEY FROM DUAL) s ON (d.CAPABILITY_KEY=s.CAPABILITY_KEY AND d.DEPENDS_ON_KEY=s.DEPENDS_ON_KEY) WHEN NOT MATCHED THEN INSERT(CAPABILITY_KEY,DEPENDS_ON_KEY) VALUES(s.CAPABILITY_KEY,s.DEPENDS_ON_KEY);
